package com.lumo.nativeapp;
import java.nio.file.*;
import org.json.*;
import java.lang.reflect.*;
public final class MerchantQrProbe {
 public static void main(String[]args)throws Exception{
  JSONArray cases=new JSONArray(Files.readString(Path.of("/tmp/lumo-native-merchant-probe/cases.json")));
  Method decoder=NativeCameraSession.class.getDeclaredMethod("decodeQr",byte[].class,int.class,int.class);decoder.setAccessible(true);
  int passed=0;
  for(int i=0;i<cases.length();i++){JSONObject c=cases.getJSONObject(i);byte[] pixels=Files.readAllBytes(Path.of(c.getString("filename")));String raw=(String)decoder.invoke(null,pixels,c.getInt("size"),c.getInt("size"));if(!c.getString("url").equals(raw)){System.out.println(c.getString("kind")+" "+c.getInt("size")+"px "+c.getInt("modules")+" modules: DECODE FAILED");continue;}NativeApprovedMerchantQr.Intent parsed=NativeApprovedMerchantQr.parse(raw);if(parsed==null||!parsed.shopId.equals("11111111-1111-4111-8111-111111111111")||!parsed.testKey.equals("a".repeat(64)))throw new AssertionError("Incorrect quote target/token");if(c.getString("kind").endsWith("fixed")&&(!parsed.requestId.equals("22222222-2222-4222-8222-222222222222")||(c.getString("kind").equals("fixed")?parsed.expectedAmount!=2500:parsed.expectedAmount!=0)))throw new AssertionError("Incorrect fixed quote");System.out.println(c.getString("kind")+" "+c.getInt("size")+"px "+c.getInt("modules")+" modules: decoder + parser PASS");passed++;}
  String sample="https://lumo-merchant-mobile.oness15.chatgpt.site/?pay=shop-101&workspace=sample";boolean rejected=false;try{NativeApprovedMerchantQr.parse(sample);}catch(IllegalArgumentException correct){rejected=true;System.out.println("Sample browser-only shop: rejected with guidance: "+correct.getMessage());}if(!rejected)throw new AssertionError("Sample must not become connected shared payment");passed++;
  System.out.println("Merchant native QR probe: "+passed+" checks passed against built 2.7.1 classes and current merchant QR generator");
 }
}
